/** Variants offered for one gender/category/type, alphabetical, NONE last. */
export function getVariants(
  gender: Gender,
  category: TraitCategoryId,
  type: VanthType,
): TraitVariant[] {
  return VARIANTS[gender][category]?.[type] ?? [];
}

/** Categories the builder can offer, in the order they are presented. */
export function getBuildableCategories(): TraitCategoryId[] {
  return [
    "type",
    "background",
    "aura",
    "hair",
    "eyes",
    "mouths",
    "facewear",
    "earrings",
    "outfit",
    "hands",
  ];
}

/**
 * Thumbnail for a trait name without knowing its Type — used by the anatomy
 * panel, which lists every variant of a category regardless of Type.
 */
export function findThumb(
  gender: Gender,
  category: TraitCategoryId,
  name: string,
): string | null {
  const byType = VARIANTS[gender][category];
  if (!byType) return null;
  for (const variants of Object.values(byType)) {
    const hit = variants.find((v) => v.name === name);
    if (hit) return hit.thumb;
  }
  return null;
}

/** A variant with no artwork at all — renders as nothing. */
export const NONE_NAME = "NONE";
